import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const s="/llamatron/assets/generators.Cy8zn4Lr.svg",u=JSON.parse('{"title":"Generators","description":"","frontmatter":{},"headers":[],"relativePath":"GENERATORS.md","filePath":"GENERATORS.md"}'),n={name:"GENERATORS.md"};function i(h,e,d,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="generators" tabindex="-1">Generators <a class="header-anchor" href="#generators" aria-label="Permalink to &quot;Generators&quot;">​</a></h1><p>A pattern says what a part is; a generator says how it is played. This page explains what generators are, how they are put to work, and the settings every kind shares. Each kind has a page of its own, listed under Generator List below, and <a href="./generators/CHAIN">Chain</a> covers the chains that run them.</p><h2 id="what-a-generator-does" tabindex="-1">What a Generator Does <a class="header-anchor" href="#what-a-generator-does" aria-label="Permalink to &quot;What a Generator Does&quot;">​</a></h2><p>A generator takes the notes a clip makes and changes them: it arpeggiates a chord, moves a figure through a progression, strums, thins out, swells, slides or hands notes to another track. A generator works on the finished clip, never on the pattern, so nothing you wrote changes. Other clips that play the same pattern are untouched unless they run the generator too, and the generator follows whatever scale, chords and tempo the clip is in when it plays: change the scene&#39;s scale and the arpeggio follows.</p><p>Generators are heard everywhere a song is: in real time as it plays, and in every export.</p><h2 id="chains" tabindex="-1">Chains <a class="header-anchor" href="#chains" aria-label="Permalink to &quot;Chains&quot;">​</a></h2><p>A clip, a scene and a track each list the generators they run, one after another. A chain is a generator too, one that runs a list of other generators in its place, so that several clips can share the same list; <a href="./generators/CHAIN">Chain</a> says how.</p><h2 id="generators-as-paint" tabindex="-1">Generators as Paint <a class="header-anchor" href="#generators-as-paint" aria-label="Permalink to &quot;Generators as Paint&quot;">​</a></h2><p>The way to think of a generator is as paint. A clip&#39;s list applies it to exactly the clips that should have it, and editing the generator afterwards changes everything painted with it at once, across every song of the set. Write one strum, paint it on every guitar part, and change how every guitar strums by editing one generator.</p><p>Some generators have a quick version as a setting of a clip, a scene or a track, like a clip&#39;s strum or a scene&#39;s density. The setting is quickest for one place; the generator is worth having for the many places that should share one shape and change together.</p><h2 id="chance" tabindex="-1">Chance <a class="header-anchor" href="#chance" aria-label="Permalink to &quot;Chance&quot;">​</a></h2><p>Every generator that chooses anything at random, a random arpeggio order or a drift&#39;s random degree, draws afresh each time the song plays or exports, so each is a new take. While a song plays in real time, one take is kept for the whole play, so an edit changes only what you edited.</p><h2 id="generator-list" tabindex="-1">Generator List <a class="header-anchor" href="#generator-list" aria-label="Permalink to &quot;Generator List&quot;">​</a></h2><p>Every generator, by name, as the picker of a new generator&#39;s type lists them.</p><table tabindex="0"><thead><tr><th>Generator</th><th>What it does</th><th>Demo</th></tr></thead><tbody><tr><td><a href="./generators/ARPEGGIATOR">Arpeggiator</a></td><td>Plays a chord one note at a time, with offsets</td><td><code>examples/learning/11_sailor_arpeggiator.yml</code></td></tr><tr><td><a href="./generators/CHORDS">Chords</a></td><td>Moves a figure through a progression of chords, or to the chords another track plays, and voices each chord nearest the one before</td><td><code>examples/learning/06_chord_progression_generator.yml</code>, <code>examples/learning/22_follow_chords.yml</code>, <code>examples/learning/05_voice_leading.yml</code></td></tr><tr><td><a href="./generators/DRIFT">Drift</a></td><td>Changes the song slowly from version A to version B</td><td><code>examples/by_genre/electronic/mainstreet_hoedown.yml</code></td></tr><tr><td><a href="./generators/GUITARIFY">Guitarify</a></td><td>Holds chords as a hand does and plays a bar of strokes on them</td><td><code>examples/learning/21_guitarify.yml</code></td></tr><tr><td><a href="./generators/HOCKET">Hocket</a></td><td>Deals one track&#39;s notes out among other tracks</td><td><code>examples/learning/17_hocket_shanty.yml</code></td></tr><tr><td><a href="./generators/MUSICIAN">Musician</a></td><td>Plays a clip as a player of the band would: by the kind of section, round the tune, with the instrument&#39;s habits</td><td><code>examples/learning/24_musician.yml</code></td></tr><tr><td><a href="./generators/PHRASING">Phrasing</a></td><td>Plays a tune in lines, as a singer would: a breath after each, a rise and fall, notes choppy or flowing</td><td><code>examples/learning/23_phrasing.yml</code></td></tr><tr><td><a href="./generators/SHAPES">Shapes</a></td><td>Ramps how many notes play, how loud and how long over a section</td><td><code>examples/by_genre/electronic/edm_density.yml</code></td></tr><tr><td><a href="./generators/TIMING">Timing</a></td><td>Plays notes on chosen steps early, late, short or sliding into the next</td><td><code>examples/learning/12_acid_glide.yml</code></td></tr></tbody></table><p><a href="./DEMOS">About Demos</a> describes every demo, and its table shows which features each one uses.</p><h2 id="generators-page" tabindex="-1">Generators Page <a class="header-anchor" href="#generators-page" aria-label="Permalink to &quot;Generators Page&quot;">​</a></h2><p><img src="'+s+'" alt="The Generators page"></p><p>Press <code>G</code> on the main screen for the Generators page, which lists every generator of the set in one list sorted by name, with its kind and how many chains, clips, scenes and tracks use it. No two generators share a name, whatever their kinds. The kinds are the Chain, Arpeggiator, Chords, Drift, Guitarify, Hocket, Musician, Phrasing, Shapes and Timing. A generator changes a clip&#39;s notes when the song plays or exports; to use one, add it to the Generators field of a clip, a scene or a track, on its own or in a chain.</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>A</code></td><td>Add one: choose its kind, and it is named after the kind and opened</td></tr><tr><td><code>ENTER</code></td><td>Edit its settings</td></tr><tr><td><code>N</code> or <code>F2</code></td><td>Rename it, which updates every chain and list that runs it</td></tr><tr><td><code>C</code></td><td>Copy it, under the next free name</td></tr><tr><td><code>/</code></td><td>Search the list as you type: <code>Tab</code> completes, <code>ENTER</code> keeps your place, <code>ESC</code> shows the whole list again</td></tr><tr><td><code>Bksp</code></td><td>Delete it after asking; it is taken out of every chain and list that runs it, and the question names up to five</td></tr></tbody></table><h2 id="enabled" tabindex="-1">Enabled <a class="header-anchor" href="#enabled" aria-label="Permalink to &quot;Enabled&quot;">​</a></h2><p>Every generator&#39;s page starts with Enabled, after its Name, on unless switched off with Space or ENTER. A generator switched off is passed over wherever a chain or a clip&#39;s, a scene&#39;s or a track&#39;s list of generators names it, so a part can be heard without it and brought back without taking it out of every list. The set file writes <code>enabled: false</code> only for a generator switched off.</p><h2 id="time-settings" tabindex="-1">Time Settings <a class="header-anchor" href="#time-settings" aria-label="Permalink to &quot;Time Settings&quot;">​</a></h2><p>Every setting of a generator that is a time, an arpeggiator&#39;s Step, a drift&#39;s or a progression&#39;s Every and a shape&#39;s Over, chooses from one list, in this order: its own first choice, such as <code>(from pattern)</code> or <code>(whole)</code>, then 1/64, 1/32, 1/16, 1/16 triplet, dotted 1/16, 1/8, 1/8 triplet, dotted 1/8, 1/4, 1/4 triplet, 1/2, and then 1, 2, 4, 8 and 16 bars, a bar being as long as the song&#39;s time signature says. A time a set file holds that isn&#39;t on the list, such as an older file&#39;s <code>2</code>, stays as it is and is offered at the end of the list.</p><h2 id="restart" tabindex="-1">Restart <a class="header-anchor" href="#restart" aria-label="Permalink to &quot;Restart&quot;">​</a></h2><p>Every generator ends its settings with Restart, which says when it starts over:</p><ul><li>&quot;every clip&quot;, the default: with every clip, as if made anew for it;</li><li>&quot;on new scene&quot;: the first time each scene plays, carrying on through the scene&#39;s repeats;</li><li>&quot;whole song&quot;: never, running along the song from its top, the scenes laid end to end, so that a scene launched by hand plays as it would at its place in the song.</li></ul><p>A generator that carries on keeps what it was doing: a progression runs on across scenes, a shape&#39;s ramp can last the whole song, a voice leading voices a scene&#39;s first chord near the last chord before, and an arpeggiator goes on with its random choices. A generator painted on several tracks gives each track a copy of its own, so that tracks line up when their patterns do.</p><h2 id="rows-of-steps" tabindex="-1">Rows of Steps <a class="header-anchor" href="#rows-of-steps" aria-label="Permalink to &quot;Rows of Steps&quot;">​</a></h2><p>A <a href="./generators/TIMING">Timing</a> generator&#39;s Rush, Drag, Shorten and Glide are each a row of 1 to 16 steps, each on (<code>●</code>) or off, running from each clip&#39;s start at its own Step, the clip&#39;s pattern&#39;s step size unless set; a note starting on a step that is on is changed. The settings page shows each row as <code>[configure]</code>. A row shorter than the pattern, 5 or 7 steps over 16, lands somewhere new each time round, so that slides, short notes and pushes move through a line that never changes. <code>ENTER</code> on Steps opens the row: Left and Right move along it, <code>Space</code> or <code>ENTER</code> turns the step under the cursor on or off, the line above the row saying what a step that is on does, and <code>I</code> and <code>D</code> insert and remove steps.</p><h2 id="shapes" tabindex="-1">Shapes <a class="header-anchor" href="#shapes" aria-label="Permalink to &quot;Shapes&quot;">​</a></h2><p>Density, Swell and Articulate shape a clip&#39;s notes over time, each a percentage that ramps from a start to an end. A <a href="./generators/SHAPES">Shapes</a> generator holds all three, and a chain names it as <code>shapes: name</code>; Density and Articulate are also set in a section of the Scene page and of the clip page, <code>+ Density</code> and <code>+ Articulate</code>. A generator in a clip&#39;s chains wins over the clip&#39;s own setting, which wins over its scene&#39;s, so that a generator can be painted on many clips and changed in one place. How loud a scene or a clip plays is set by its Velocity and its velocity ramps, which a Shapes generator&#39;s Swell scales again: see <a href="./SCENES#velocity-and-velocity-ramps">Velocity and Velocity Ramps</a>. Every setting left blank plays as 100%, changing nothing.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Start, End</td><td>The percentage at the start and at the end, ramping from one to the other. <code>Bksp</code> leaves it blank, which plays as 100%.</td></tr><tr><td>Over</td><td>How long one ramp lasts: &quot;(whole)&quot;, the default, the whole scene for a scene&#39;s and the whole clip for a clip&#39;s or a generator&#39;s, or a time from the list every time setting shares, such as &quot;1/4&quot; or &quot;2 bars&quot;.</td></tr><tr><td>Then</td><td>What happens after a ramp when the clip goes on: &quot;hold&quot; stays at the end, &quot;repeat&quot; starts the ramp again, and &quot;bounce&quot; ramps back.</td></tr></tbody></table>',33)])])}const f=t(n,[["render",i]]);export{u as __pageData,f as default};
